namespace ndn {

  class VideoPlayer
  {
    public:

      VideoPlayer();
      void
      playbin_uri (std::string filename);
      void
      playbin_appsrc_init ();
      void
      playbin_appsrc_data (const uint8_t *buffer, size_t bufferSize);

    private:
      struct _DataNode
      {
        gsize length;
        guint8 *data;
      };
      typedef struct _DataNode DataNode;

      struct _App
      {
        GstElement *playbin;
        GstElement *appsrc;

        GMainLoop *loop;
        guint sourceid;

        guint8 *data;
        gsize length;
        guint64 offset;

        std::deque<DataNode> dataQue;

      };
      typedef struct _App App;
      App s_app;

      #define CHUNK_SIZE  1024*1024

      static gboolean
      read_data (App * app)
      {
        GstBuffer *buffer;
        guint len;
        GstFlowReturn ret;

        if((app -> dataQue).size() == 0)
        {
          return TRUE; 
        }

        if(app -> data == NULL)
        {
          DataNode tmpNode = (app -> dataQue).front();
          app -> data = tmpNode.data;
          app -> length = tmpNode.length;
          app -> offset = 0;
        }
        std::cout << "Read Data Offset" << app->offset <<std::endl;
        buffer = gst_buffer_new ();

        //std::cout << "I'm reading" <<std::endl;
        if (app->offset >= app->length) {
          /* we are EOS, send end-of-stream and remove the source */
          app -> data = NULL;
          (app -> dataQue).pop_front();
          std::cout << "Meet the end" <<std::endl;
          //g_signal_emit_by_name (app->appsrc, "end-of-stream", &ret);
          return TRUE;
        }

        /* read the next chunk */
        len = CHUNK_SIZE;
        if (app->offset + len > app->length)
          len = app->length - app->offset;
        buffer = gst_buffer_new_wrapped (app->data + app->offset, len);
        g_signal_emit_by_name (app->appsrc, "push-buffer", buffer, &ret);
      //  gst_buffer_unref (buffer);
        if (ret != GST_FLOW_OK) {
          /* some error, stop sending data */
          return FALSE;
        }
        app->offset += len;
        return TRUE;
      }

      /* This signal callback is called when appsrc needs data, we add an idle handler
       * to the mainloop to start pushing data into the appsrc */
      static void
      start_feed (GstElement * playbin, guint size, App * app)
      {
        if (app->sourceid == 0) {
          app->sourceid = g_idle_add ((GSourceFunc) read_data, app);
        }
      }

